<?php $this->layout('layouts/studio'); ?>
<section class="studio-page-header"><div><small>GESTÃO DOCUMENTAL</small><h2>Documentos</h2><p>Arquivos operacionais relacionados aos condomínios.</p></div><button class="studio-btn primary" type="button" onclick="document.querySelector('[data-document-form]').hidden=false"><ion-icon name="cloud-upload-outline"></ion-icon>Enviar documento</button></section>
<section class="studio-panel" data-document-form hidden><header><div><small>NOVO DOCUMENTO</small><h2>Upload seguro</h2></div></header><form class="studio-form" method="post" action="<?= url('/operation/documentos') ?>" enctype="multipart/form-data"><?= csrf_input() ?><div class="studio-fields-two"><label>Condomínio *<select name="condominium_id" required><option value="">Selecione</option><?php foreach($condominiums as $c): ?><option value="<?= $c->id ?>"><?= htmlspecialchars($c->name) ?></option><?php endforeach; ?></select></label><label>Título *<input name="title" required></label><label>Categoria *<select name="category" required><option value="">Selecione</option><?php foreach(['Atas','Convenção','Regimento','Contratos','Orçamentos','Laudos','Seguros','Certificados','Comunicados','Administrativo'] as $cat): ?><option><?= $cat ?></option><?php endforeach; ?></select></label><label>Arquivo *<input type="file" name="document_file" required></label><label>Data do documento<input type="date" name="document_date"></label><label>Validade<input type="date" name="valid_until"></label><label>Demanda<select name="demand_id"><option value="">Sem vínculo</option><?php foreach($demands as $d): ?><option value="<?= $d->id ?>"><?= htmlspecialchars($d->protocol.' · '.$d->title) ?></option><?php endforeach; ?></select></label><label>Fornecedor<select name="supplier_id"><option value="">Sem vínculo</option><?php foreach($suppliers as $s): ?><option value="<?= $s->id ?>"><?= htmlspecialchars($s->name) ?></option><?php endforeach; ?></select></label></div><div class="studio-form-actions"><button class="studio-btn primary" type="submit">Salvar documento</button><button class="studio-btn" type="button" onclick="this.closest('[data-document-form]').hidden=true">Cancelar</button></div></form></section>
<section class="studio-panel studio-list-panel"><header><div><small>ARQUIVOS</small><h2><?= count($items) ?> documento(s)</h2></div><label class="operation-resource-search"><ion-icon name="search-outline"></ion-icon><input type="search" placeholder="Buscar documento" oninput="document.querySelectorAll('[data-doc]').forEach(e=>e.hidden=!e.dataset.doc.includes(this.value.toLowerCase()))"></label></header><div class="studio-table-scroll"><table class="studio-table"><thead><tr><th>Documento</th><th>Condomínio</th><th>Categoria</th><th>Validade</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php if(!$items): ?><tr><td colspan="6"><div class="studio-empty">Nenhum documento encontrado.</div></td></tr><?php endif; ?><?php foreach($items as $item): ?><tr data-doc="<?= htmlspecialchars(mb_strtolower($item->title.' '.$item->condominium_name.' '.$item->category)) ?>"><td><strong><?= htmlspecialchars($item->title) ?></strong><small><?= htmlspecialchars($item->original_name) ?></small></td><td><?= htmlspecialchars($item->condominium_name) ?></td><td><?= htmlspecialchars($item->category) ?></td><td><?= $item->valid_until?date('d/m/Y',strtotime($item->valid_until)):'—' ?></td><td><span class="studio-proposal-status <?= htmlspecialchars($item->status) ?>"><?= htmlspecialchars($item->status) ?></span></td><td><a class="studio-icon-action" href="<?= url('/'.CONF_UPLOAD_DIR.'/'.$item->file_path) ?>" download title="Baixar"><ion-icon name="download-outline"></ion-icon></a></td></tr><?php endforeach; ?></tbody></table></div></section>
